    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        // Get the number of vertices in each partition
        int n = Integer.parseInt(getParameter("n"));
        int m = Integer.parseInt(getParameter("m"));

        // Create vertices for the first partition
        for (int i = 0; i < n; i++) {
            String vertexName = "A" + i;
            V vertex = target.addVertex();
            resultMap.put(vertexName, vertex);
        }

        // Create vertices for the second partition
        for (int j = 0; j < m; j++) {
            String vertexName = "B" + j;
            V vertex = target.addVertex();
            resultMap.put(vertexName, vertex);
        }

        // Connect every vertex in the first partition to every vertex in the second partition
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                V vertexA = resultMap.get("A" + i);
                V vertexB = resultMap.get("B" + j);
                target.addEdge(vertexA, vertexB);
            }
        }
    }
