public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name cannot be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("Mappings cannot be null");
    }

    Mappings diff = new Mappings();
    Map<String, Object> currentMappings = getCurrentMappings(tableName);

    if (currentMappings == null) {
        return diff;
    }

    Map<String, Object> inputMappings = mappings.getFields();
    if (inputMappings == null) {
        return diff;
    }

    for (Map.Entry<String, Object> entry : currentMappings.entrySet()) {
        String fieldName = entry.getKey();
        if (!inputMappings.containsKey(fieldName)) {
            diff.addField(fieldName, entry.getValue());
        }
    }

    return diff;
}

