public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new NullPointerException("str must not be null");
    }
    if (session == null) {
        throw new NullPointerException("session must not be null");
    }
    if (lb == null) {
        throw new NullPointerException("lb must not be null");
    }

    final int length = str.length();
    if (length == 0) {
        return lb;
    }

    // Estimate the number of bytes needed for UTF-8 encoding
    int estimatedBytes = 0;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            estimatedBytes += 1;
        } else if (c < 0x800) {
            estimatedBytes += 2;
        } else if (c < 0xD800 || c > 0xDFFF) {
            estimatedBytes += 3;
        } else {
            // Surrogate pair
            estimatedBytes += 4;
            i++; // Skip the low surrogate
        }
    }

    // Ensure the buffer has enough space
    if (lb.capacity() < estimatedBytes) {
        lb.ensureCapacity(estimatedBytes);
    }

    // Write the UTF-8 encoded bytes
    int offset = lb.offset();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.writeByte((byte) c);
        } else if (c < 0x800) {
            lb.writeByte((byte) (0xC0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        } else if (c < 0xD800 || c > 0xDFFF) {
            lb.writeByte((byte) (0xE0 | (c >> 12)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        } else {
            // Surrogate pair
            if (i + 1 >= length) {
                throw new IllegalArgumentException("Unpaired surrogate at index " + i);
            }
            char low = str.charAt(i + 1);
            if (low < 0xDC00 || low > 0xDFFF) {
                throw new IllegalArgumentException("Invalid low surrogate at index " + (i + 1));
            }
            int codePoint = 0x10000 + ((c - 0xD800) << 10) + (low - 0xDC00);
            lb.writeByte((byte) (0xF0 | (codePoint >> 18)));
            lb.writeByte((byte) (0x80 | ((codePoint >> 12) & 0x3F)));
            lb.writeByte((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (codePoint & 0x3F)));
            i++; // Skip the low surrogate
        }
    }

    return lb;
}
