    final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        try {
            final int length = readUnsignedShort();
            if (length > charBuffer.length) {
                throw new IllegalArgumentException("charBuffer is too small to hold the UTF-8 string of length " + length);
            }
            int charIndex = 0;
            for (int i = 0; i < length; i++) {
                int b = readUnsignedByte();
                if ((b & 0x80) == 0) {
                    charBuffer[charIndex++] = (char) b;
                } else if ((b & 0xE0) == 0xC0) {
                    int b2 = readUnsignedByte();
                    charBuffer[charIndex++] = (char) (((b & 0x1F) << 6) | (b2 & 0x3F));
                } else if ((b & 0xF0) == 0xE0) {
                    int b2 = readUnsignedByte();
                    int b3 = readUnsignedByte();
                    charBuffer[charIndex++] = (char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
                } else {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding at byte " + b);
                }
            }
            return new String(charBuffer, 0, charIndex);
        } catch (Exception e) {
            throw new RuntimeException("Error reading UTF-8 constant pool entry at index " + constantPoolEntryIndex, e);
