protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    if (graph == null) {
        return null;
    }

    // Build a map from vertex to its adjacent edges in the tour
    Map<V, Set<E>> vertexToEdges = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (source != null) {
            vertexToEdges.computeIfAbsent(source, k -> new HashSet<>()).add(edge);
        }
        if (target != null) {
            vertexToEdges.computeIfAbsent(target, k -> new HashSet<>()).add(edge);
        }
    }

    // Find a starting vertex (one with degree 1 if exists, otherwise any vertex)
    V startVertex = null;
    for (Map.Entry<V, Set<E>> entry : vertexToEdges.entrySet()) {
        if (entry.getValue().size() == 1) {
            startVertex = entry.getKey();
            break;
        }
    }
    if (startVertex == null) {
        startVertex = vertexToEdges.keySet().iterator().next();
    }

    // Build the path by traversing the tour
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> usedEdges = new HashSet<>();

    V currentVertex = startVertex;
    vertices.add(currentVertex);

    while (true) {
        Set<E> availableEdges = vertexToEdges.get(currentVertex);
        if (availableEdges == null || availableEdges.isEmpty()) {
            break;
        }

        // Find an unused edge
        E nextEdge = null;
        for (E edge : availableEdges) {
            if (!usedEdges.contains(edge)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            break;
        }

        usedEdges.add(nextEdge);
        edges.add(nextEdge);

        // Determine the next vertex
        V source = graph.getEdgeSource(nextEdge);
        V target = graph.getEdgeTarget(nextEdge);
        V nextVertex;
        if (source.equals(currentVertex)) {
            nextVertex = target;
        } else {
            nextVertex = source;
        }

        vertices.add(nextVertex);
        currentVertex = nextVertex;

        // If we've used all edges, stop
        if (usedEdges.size() == tour.size()) {
            break;
        }
    }

    // Create the graph path
    return new GraphPath<>(graph, vertices, edges);
}
