private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("list must not be null");
    }
    if (list == this) {
        return;
    }
    ListNode<E> head = list.head;
    if (head == null) {
        return;
    }
    ListNode<E> tail = list.tail;
    // Detach from the source list
    head.prev = null;
    tail.next = null;
    list.head = null;
    list.tail = null;
    list.size = 0;
    // Attach to this list
    if (this.head == null) {
        this.head = head;
        this.tail = tail;
    } else {
        this.tail.next = head;
        head.prev = this.tail;
        this.tail = tail;
    }
    this.size += list.size;
}

