public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Normalize the base path: ensure it ends with a separator if it's a directory
    String normalizedPath = path;
    if (!normalizedPath.endsWith("/") && !normalizedPath.endsWith("\\")) {
        // Check if the path looks like a file (has an extension) or directory
        // For simplicity, we'll just append the relative path with a separator
        normalizedPath = normalizedPath + "/";
    }

    // Remove leading separator from relative path if present
    String normalizedRelative = relativePath;
    while (normalizedRelative.startsWith("/") || normalizedRelative.startsWith("\\")) {
        normalizedRelative = normalizedRelative.substring(1);
    }

    // Combine the paths
    String result = normalizedPath + normalizedRelative;

    // Normalize the result: resolve "." and ".." segments
    String[] parts = result.split("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else {
            stack.push(part);
        }
    }

    // Reconstruct the path
    StringBuilder sb = new StringBuilder();
    // If the original path started with a separator, preserve it
    if (path.startsWith("/") || path.startsWith("\\")) {
        sb.append("/");
    }

    while (!stack.isEmpty()) {
        String part = stack.pop();
        if (sb.length() > 0) {
            sb.append("/");
        }
        sb.append(part);
    }

    return sb.toString();
}
